package dev.cazajefes;
import org.junit.Test;
import static org.junit.Assert.*;
import org.bukkit.Material;
import org.bukkit.util.Vector;
public class RangedReworkTest {
 @Test public void unstableChargeProgressionMatchesHearts(){for(int n=1;n<=4;n++){assertEquals(3*n,RangedProcRules.extraDamage("carga_inestable",n),0);assertEquals(1.5*n,RangedProcRules.extraDamage("carga_inestable",n)/2,0);}assertEquals(4,RangedRareCatalog.get("carga_inestable").max());assertTrue(RareCompatibility.accepts("carga_inestable",Material.BOW));assertTrue(RareCompatibility.accepts("carga_inestable",Material.CROSSBOW));}
 @Test public void procProbabilityIncreasesAndRollBoundaryIsExclusive(){for(String id:new String[]{"carga_inestable","cerrojo_vacio","relevo_fantasma","pulso_retorno"}){double prior=0;for(int n=1;n<=RangedRareCatalog.get(id).max();n++){double chance=RangedProcRules.chance(id,n);assertTrue(chance>prior);assertTrue(chance<1);assertTrue(RangedProcRules.rolls(id,n,chance-.00001));assertFalse(RangedProcRules.rolls(id,n,chance));prior=chance;}}assertEquals(.6,RangedProcRules.chance("cerrojo_vacio",5),.00001);}
 @Test public void sidestepsAreBoundedAtEveryLevel(){assertEquals(4,RangedRareCatalog.get("relevo_fantasma").max());for(int n=1;n<=4;n++){assertEquals(n,RangedProcRules.stepDistance(n,0),0);assertEquals(n+1,RangedProcRules.stepDistance(n,1),0);assertEquals(n+.5,RangedProcRules.stepDistance(n,.5),0);}}
 @Test public void returnPulseWorksOnSingleImpactWithoutRangeCombo(){assertTrue(RangedProcRules.direct("pulso_retorno"));for(int n=1;n<=3;n++)assertEquals(n,RangedProcRules.extraDamage("pulso_retorno",n),0);assertTrue(RangedProcRules.direct("marca_cazador"));assertTrue(RangedProcRules.direct("ojo_tormenta"));assertEquals("Herida del Eclipse",RareDefinitions.get("marca_cazador").title());assertEquals("Descarga de Tormenta",RareDefinitions.get("ojo_tormenta").title());}
 @Test public void formerSharedPowersHaveEquipmentDestinations(){assertEquals(RareCompatibility.Group.ARMOR,RareCompatibility.property("blinding"));assertTrue(RareCompatibility.accepts("blinding",Material.DIAMOND_HELMET));assertFalse(RareCompatibility.accepts("blinding",Material.DIAMOND_CHESTPLATE));assertTrue(RareCompatibility.accepts("calllighting",Material.NETHERITE_SWORD));assertFalse(RareCompatibility.accepts("calllighting",Material.TRIDENT));assertTrue(RareCompatibility.accepts("slow",Material.BOW));assertFalse(RareCompatibility.accepts("slow",Material.CROSSBOW));}
 @Test public void aquaticPursuitCanDiveVerticallyInsteadOfFloating(){Vector down=AquaticCombat.pursuit(new Vector(0,-8,0),false),up=AquaticCombat.pursuit(new Vector(0,8,0),false);assertEquals(-.55,down.getY(),.00001);assertEquals(.45,up.getY(),.00001);assertTrue(AquaticCombat.pursuit(new Vector(4,-3,0),false).getY()<0);assertEquals(0,AquaticCombat.pursuit(new Vector(),false).length(),0);}
}
